/*
 * Synchronize artifacts generated by @kiskadee/web-builder with the
 * @kiskadee/showcase project (Next app).
 *
 * Source: packages/web-builder/build/**
 * Target: packages/showcase/public/build/**
 *
 * Usage:
 *   pnpm sync-showcase-artifacts
 *
 * Prerequisite: run the @kiskadee/web-builder build beforehand to
 * populate packages/web-builder/build.
 */

const fs = require('node:fs');
const fsp = require('node:fs/promises');
const path = require('node:path');

// When this script lived at the monorepo root, __dirname already pointed to
// the repo root and we could resolve "packages/web-builder/build" directly.
// After moving the script to packages/web-builder/scripts, we must:
// - treat the web-builder package root as the source base (build directory),
// - and still resolve the showcase target relative to the monorepo root.

// packages/web-builder/scripts -> packages/web-builder
const webBuilderRoot = __dirname ? path.resolve(__dirname, '..') : process.cwd();

// Source: packages/web-builder/build
const srcDir = path.resolve(webBuilderRoot, 'build');

// Monorepo root: packages/web-builder -> ../.. -> <repoRoot>
const repoRoot = path.resolve(webBuilderRoot, '..', '..');

// Target: packages/showcase/public/build
const dstDir = path.resolve(repoRoot, 'packages', 'showcase', 'public', 'build');

async function existsDir(dir) {
  try {
    const stat = await fsp.stat(dir);
    return stat.isDirectory();
  } catch {
    return false;
  }
}

async function removeDirContents(dir) {
  if (!(await existsDir(dir))) return;

  const entries = await fsp.readdir(dir, { withFileTypes: true });
  await Promise.all(
    entries.map(async (entry) => {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await fs.promises.rm(full, { recursive: true, force: true });
      } else {
        await fsp.unlink(full);
      }
    })
  );
}

async function copyRecursive(src, dst) {
  const entries = await fsp.readdir(src, { withFileTypes: true });

  await fsp.mkdir(dst, { recursive: true });

  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const dstPath = path.join(dst, entry.name);

    if (entry.isDirectory()) {
      await copyRecursive(srcPath, dstPath);
    } else if (entry.isFile()) {
      await fsp.copyFile(srcPath, dstPath);
    }
  }
}

async function main() {
  if (!(await existsDir(srcDir))) {
    console.error('[sync-showcase-artifacts] Source directory not found:', srcDir);
    console.error('Make sure you have run the @kiskadee/web-builder build beforehand.');
    process.exitCode = 1;
    return;
  }

  console.log('[sync-showcase-artifacts] Source:', srcDir);
  console.log('[sync-showcase-artifacts] Target:', dstDir);

  await fsp.mkdir(dstDir, { recursive: true });
  await removeDirContents(dstDir);
  await copyRecursive(srcDir, dstDir);

  console.log('[sync-showcase-artifacts] Artifacts synchronized successfully.');
}

main().catch((err) => {
  console.error('[sync-showcase-artifacts] Unexpected error:', err);
  process.exitCode = 1;
});
